(() => {
  'use strict';
  const canvas = document.getElementById('game'), ctx = canvas.getContext('2d');
  const ui = Object.fromEntries(['levelText','hpBar','hpText','mpBar','mpText','xpText','xpBar','attackText','goldText','questBar','questCount','combatFeed','notice','bossWarning','levelUp','newLevel','levelClose','defeat','toast','questCard','questToggle','soundBtn','attackBtn','skill1','skill2','skill3','mobileAttack','mobileDash','joystick','joyKnob'].map(id=>[id,document.getElementById(id)]));
  const rand=(a,b)=>a+Math.random()*(b-a), clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
  let W=0,H=0,dpr=1,last=0,time=0,worldSeed=761;
  const player={x:0,y:0,dx:0,dy:0,hp:100,maxHp:100,mp:60,maxMp:60,level:1,xp:0,nextXp:100,gold:0,attack:12,faceX:1,faceY:0,invuln:0,attackTimer:0,attackCd:0,dashCd:0,ultimate:0,dead:false};
  let enemies=[],particles=[],slashes=[],texts=[],decor=[],kills=0,bossSpawned=false,boss=null,questDone=false,noticeTimer=0,toastTimer=0,shake=0;
  const keys={}, skillState={q:0,e:0,r:0}, colors={shadow:'#b58aff',flame:'#ff9c6d',cyan:'#6ce3ef',gold:'#f4d276'};
  const skillDefs={q:{cost:20,cd:5,name:'그림자 돌진'},e:{cost:30,cd:8,name:'월광참'},r:{cost:50,cd:22,name:'그림자 군주'}};
  let mobileVector={x:0,y:0},joystickActive=false,soundOn=false,audio;
  function resize(){dpr=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=Math.floor(W*dpr);canvas.height=Math.floor(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0)}
  addEventListener('resize',resize);resize();
  function say(text){ui.toast.textContent=text;ui.toast.classList.add('show');toastTimer=2.1}
  function notify(text){ui.notice.querySelector('span').textContent=text;ui.notice.classList.add('show');noticeTimer=2.8}
  function feed(text,type=''){const el=document.createElement('div');el.className='feed-line '+type;el.textContent=text;ui.combatFeed.prepend(el);while(ui.combatFeed.children.length>4)ui.combatFeed.lastChild.remove();setTimeout(()=>el.remove(),4800)}
  function sound(freq=360,duration=.08,type='sine'){if(!soundOn)return;try{audio??=new (window.AudioContext||window.webkitAudioContext)();const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(.055,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+duration)}catch{}}
  function worldPoint(x,y){return {x:W/2+x-player.x,y:H/2+15+y-player.y}}
  function addParticle(x,y,color,n=12,power=130,size=3){for(let i=0;i<n;i++){let a=rand(0,Math.PI*2),v=rand(power*.25,power),life=rand(.25,.65);particles.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,life,max:life,size:rand(1,size),color})}}
  function floatText(x,y,text,color='#fff',size=13){texts.push({x,y,text,color,size,life:.8,max:.8,vy:-32})}
  function spawnEnemy(x,y,big=false){let e={x,y,hp:big?240:38+player.level*7,maxHp:big?240:38+player.level*7,r:big?27:16,speed:big?37:rand(42,57),attack:big?16:7+player.level,cd:rand(.5,1.8),hit:0,phase:rand(0,8),seed:rand(0,999),big,dead:false};enemies.push(e);return e}
  function initWorld(){for(let i=0;i<38;i++){const a=rand(0,Math.PI*2),r=rand(270,1100);decor.push({x:Math.cos(a)*r,y:Math.sin(a)*r,type:Math.random()<.54?'stone':'tree',scale:rand(.65,1.5),rot:rand(0,6.28),seed:rand(0,999)})}for(let i=0;i<5;i++){let a=rand(0,6.28),r=rand(210,390);spawnEnemy(Math.cos(a)*r,Math.sin(a)*r)}}
  initWorld();
  function nearestEnemy(range=Infinity){let best=null,bd=range;for(const e of enemies){if(e.dead)continue;const d=Math.hypot(e.x-player.x,e.y-player.y);if(d<bd){bd=d;best=e}}return best}
  function faceTarget(){let e=nearestEnemy(240);if(e){let d=Math.hypot(e.x-player.x,e.y-player.y)||1;player.faceX=(e.x-player.x)/d;player.faceY=(e.y-player.y)/d}}
  function damageEnemy(e,damage,knock=0,color=colors.gold){if(e.dead)return;e.hp-=damage;e.hit=.17;floatText(e.x,e.y-e.r-8,Math.round(damage),color,e.big?17:13);addParticle(e.x,e.y,color,e.big?9:6,75,2.4);if(knock){const d=Math.hypot(e.x-player.x,e.y-player.y)||1;e.x+=((e.x-player.x)/d)*knock;e.y+=((e.y-player.y)/d)*knock}if(e.hp<=0){e.dead=true;kills++;player.xp+=e.big?120:32;player.gold+=e.big?100:12;addParticle(e.x,e.y,e.big?colors.cyan:colors.shadow,e.big?38:20,180,4);floatText(e.x,e.y-25,e.big?'수호자 격파!':'처치!',e.big?colors.cyan:colors.gold,14);feed(e.big?'균열의 수호자를 처치했습니다!':'그림자 몬스터 처치  +32 XP','good');if(!e.big){if(kills<5)document.getElementById('questCount').textContent=`${Math.min(kills,5)} / 5`;if(kills>=5&&!bossSpawned)spawnBoss()}else{questDone=true;document.getElementById('questCount').textContent='완료';document.getElementById('questBar').style.width='100%';player.xp+=120;player.gold+=80;feed('의뢰 완료! +120 XP  +80 G','gold');notify('의뢰 완료 — 보상을 획득했습니다')}}}
  function spawnBoss(){bossSpawned=true;let a=Math.atan2(player.faceY,player.faceX),x=player.x-Math.cos(a)*310,y=player.y-Math.sin(a)*310;boss=spawnEnemy(x,y,true);ui.bossWarning.classList.add('show');setTimeout(()=>ui.bossWarning.classList.remove('show'),3500);notify('균열의 수호자가 나타났습니다');feed('강력한 기운이 다가옵니다...','damage');shake=10}
  function attack(){if(player.dead||player.attackCd>0)return;faceTarget();player.attackCd=.42;player.attackTimer=.23;sound(290,.09,'triangle');let e=nearestEnemy(94);let d=player.faceX*player.faceX+player.faceY*player.faceY;if(e){let dot=((e.x-player.x)*player.faceX+(e.y-player.y)*player.faceY)/(Math.hypot(e.x-player.x,e.y-player.y)||1);if(dot<-.1)e=null}slashes.push({x:player.x,y:player.y,a:Math.atan2(player.faceY,player.faceX),life:.28,max:.28,color:'#e9e9ff',r:62});if(e)damageEnemy(e,player.attack,16,'#f2e7c7');else addParticle(player.x+player.faceX*38,player.y+player.faceY*38,'#d7eaff',4,60,2)}
  function useSkill(key){if(player.dead)return;const def=skillDefs[key];if(skillState[key]>0){say('스킬이 아직 준비되지 않았습니다');return}if(player.mp<def.cost){say('마나가 부족합니다');return}player.mp-=def.cost;skillState[key]=def.cd;faceTarget();sound(key==='r'?100:key==='e'?210:150,.28,'sawtooth');
    if(key==='q'){let tx=player.x+player.faceX*145,ty=player.y+player.faceY*145;player.x=tx;player.y=ty;player.invuln=.38;slashes.push({x:player.x-player.faceX*70,y:player.y-player.faceY*70,a:Math.atan2(player.faceY,player.faceX),life:.45,max:.45,color:colors.shadow,r:95});addParticle(player.x,player.y,colors.shadow,24,170,4);let hit=enemies.filter(e=>!e.dead&&Math.hypot(e.x-player.x,e.y-player.y)<100);hit.forEach(e=>damageEnemy(e,38+player.level*4,32,colors.shadow));if(!hit.length)floatText(player.x,player.y-28,'그림자 돌진',colors.shadow,12)}
    if(key==='e'){slashes.push({x:player.x,y:player.y,a:Math.atan2(player.faceY,player.faceX),life:.55,max:.55,color:colors.flame,r:180});addParticle(player.x+player.faceX*75,player.y+player.faceY*75,colors.flame,34,170,4);let hit=enemies.filter(e=>!e.dead&&Math.hypot(e.x-player.x,e.y-player.y)<182);hit.forEach(e=>damageEnemy(e,58+player.level*7,48,colors.flame));if(!hit.length)floatText(player.x,player.y-30,'월광참',colors.flame,14);shake=5}
    if(key==='r'){player.ultimate=7;player.invuln=1.1;addParticle(player.x,player.y,colors.cyan,60,250,5);slashes.push({x:player.x,y:player.y,a:0,life:1,max:1,color:colors.cyan,r:260,ring:true});let hit=enemies.filter(e=>!e.dead&&Math.hypot(e.x-player.x,e.y-player.y)<270);hit.forEach(e=>damageEnemy(e,95+player.level*10,66,colors.cyan));floatText(player.x,player.y-52,'그림자 군주',colors.cyan,16);shake=13;notify('그림자 군주 — 모든 적에게 강타')}
  }
  function dodge(){if(player.dead||player.dashCd>0)return;player.dashCd=1.25;player.invuln=.5;let m=Math.hypot(player.dx,player.dy);if(m>.1){player.x+=player.dx/m*115;player.y+=player.dy/m*115}else{faceTarget();player.x+=player.faceX*115;player.y+=player.faceY*115}addParticle(player.x,player.y,colors.shadow,16,130,3);slashes.push({x:player.x,y:player.y,a:0,life:.35,max:.35,color:colors.shadow,r:80,ring:true});sound(450,.1,'sine')}
  function levelUp(){while(player.xp>=player.nextXp){player.xp-=player.nextXp;player.level++;player.nextXp=Math.round(player.nextXp*1.35);player.maxHp+=18;player.maxMp+=8;player.attack+=4;player.hp=player.maxHp;player.mp=player.maxMp;ui.newLevel.textContent=`LEVEL ${player.level}`;ui.levelUp.classList.add('active');sound(660,.45,'sine');feed(`레벨 업! Lv.${player.level} — 공격력 +4`,'gold')}}
  function update(dt){time+=dt;if(noticeTimer>0&&(noticeTimer-=dt)<=0)ui.notice.classList.remove('show');if(toastTimer>0&&(toastTimer-=dt)<=0)ui.toast.classList.remove('show');for(const k in skillState)skillState[k]=Math.max(0,skillState[k]-dt);player.attackCd=Math.max(0,player.attackCd-dt);player.attackTimer=Math.max(0,player.attackTimer-dt);player.invuln=Math.max(0,player.invuln-dt);player.ultimate=Math.max(0,player.ultimate-dt);player.dashCd=Math.max(0,player.dashCd-dt);player.mp=Math.min(player.maxMp,player.mp+dt*2.7);
    let ix=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0)+mobileVector.x,iy=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0)+mobileVector.y,m=Math.hypot(ix,iy);if(m>1){ix/=m;iy/=m}player.dx=ix;player.dy=iy;let speed=player.ultimate?190:145;player.x+=ix*speed*dt;player.y+=iy*speed*dt;if(m>.08){player.faceX=ix;player.faceY=iy}
    for(const e of enemies){if(e.dead)continue;e.phase+=dt;e.cd-=dt;e.hit=Math.max(0,e.hit-dt);let dx=player.x-e.x,dy=player.y-e.y,d=Math.hypot(dx,dy)||1;if(d>e.r+25){e.x+=dx/d*e.speed*dt;e.y+=dy/d*e.speed*dt}else if(e.cd<=0&&player.invuln<=0){e.cd=e.big?1.15:1.55;player.hp-=e.attack;shake=4;addParticle(player.x,player.y,'#fa6878',9,100,3);floatText(player.x,player.y-22,`-${e.attack}`,'#ff7782');feed(`피격! -${e.attack} HP`,'damage');sound(100,.12,'square');if(player.hp<=0){player.hp=0;player.dead=true;ui.defeat.classList.add('show');setTimeout(()=>{if(player.dead){player.hp=player.maxHp;player.mp=player.maxMp;player.x=0;player.y=0;player.dead=false;ui.defeat.classList.remove('show');notify('성역에서 부활했습니다')}},2200)}}}
    if(!bossSpawned&&enemies.filter(e=>!e.dead).length<3&&kills<5&&Math.random()<dt*.22){let a=rand(0,6.28),r=rand(280,460);spawnEnemy(player.x+Math.cos(a)*r,player.y+Math.sin(a)*r)}
    for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=Math.pow(.08,dt);p.vy*=Math.pow(.08,dt);p.life-=dt}particles=particles.filter(p=>p.life>0);for(const s of slashes)s.life-=dt;slashes=slashes.filter(s=>s.life>0);for(const t of texts){t.y+=t.vy*dt;t.life-=dt}texts=texts.filter(t=>t.life>0);levelUp();render();updateUI()}

function drawGround(){ctx.fillStyle='#111b1d';ctx.fillRect(0,0,W,H);const step=70,ox=((W/2-player.x)%step+step)%step,oy=((H/2+15-player.y)%step+step)%step;ctx.strokeStyle='rgba(165,186,159,.055)';ctx.lineWidth=1;ctx.beginPath();for(let x=ox;x<W;x+=step){ctx.moveTo(x,0);ctx.lineTo(x,H)}for(let y=oy;y<H;y+=step){ctx.moveTo(0,y);ctx.lineTo(W,y)}ctx.stroke();const g=ctx.createRadialGradient(W/2,H/2,40,W/2,H/2,Math.max(W,H)*.65);g.addColorStop(0,'rgba(91,119,90,.16)');g.addColorStop(.65,'rgba(14,32,28,.05)');g.addColorStop(1,'rgba(3,8,13,.5)');ctx.fillStyle=g;ctx.fillRect(0,0,W,H)}
function drawRuin(x,y,s,rot){ctx.save();ctx.translate(x,y);ctx.rotate(rot);ctx.fillStyle='#151d1c';ctx.globalAlpha=.95;ctx.fillRect(-15*s,-9*s,30*s,18*s);ctx.strokeStyle='#4b5950';ctx.lineWidth=2*s;ctx.strokeRect(-15*s,-9*s,30*s,18*s);ctx.fillStyle='#29352e';ctx.fillRect(-12*s,-7*s,24*s,4*s);ctx.fillStyle='#756f58';ctx.fillRect(-19*s,-12*s,7*s,4*s);ctx.fillRect(12*s,8*s,9*s,5*s);ctx.restore()}
function drawTree(x,y,s,seed){ctx.save();ctx.translate(x,y);ctx.fillStyle='#101715';ctx.fillRect(-3*s,-9*s,6*s,18*s);for(let i=0;i<3;i++){ctx.beginPath();ctx.moveTo(0,(-34+i*9)*s);ctx.lineTo(-14*s,(i*6)*s);ctx.lineTo(13*s,(i*6)*s);ctx.closePath();ctx.fillStyle=['#172320','#1c2924','#202b25'][i];ctx.fill();ctx.strokeStyle='#3d5144';ctx.lineWidth=.8;ctx.stroke()}if(seed%4<1){ctx.fillStyle='#a84f75';ctx.shadowColor='#ef5b9b';ctx.shadowBlur=10;ctx.beginPath();ctx.arc(4*s,-23*s,1.8*s,0,6.28);ctx.fill()}ctx.restore()}
function drawDecor(){for(const d of decor){const p=worldPoint(d.x,d.y);if(p.x< -100||p.x>W+100||p.y< -100||p.y>H+100)continue;if(d.type==='stone')drawRuin(p.x,p.y,d.scale,d.rot);else drawTree(p.x,p.y,d.scale,d.seed)}}
function drawEnemy(e){const p=worldPoint(e.x,e.y),r=e.r,phase=e.phase;ctx.save();ctx.translate(p.x,p.y);ctx.globalAlpha=.28;ctx.fillStyle='#000';ctx.beginPath();ctx.ellipse(0,r*.73,r*1.35,r*.47,0,0,6.28);ctx.fill();ctx.globalAlpha=1;const hue=e.big?'#5ad6dc':'#a97be4',glow=e.big?'#4edce6':'#a968ff';ctx.shadowColor=glow;ctx.shadowBlur=e.big?22:14;ctx.fillStyle=e.hit>0?'#f4d8ff':(e.big?'#3b5862':'#343047');ctx.beginPath();ctx.moveTo(-r*.76,r*.45);ctx.quadraticCurveTo(-r*1.15,-r*.25,-r*.46,-r*.96);ctx.lineTo(-r*.18,-r*.65);ctx.quadraticCurveTo(0,-r*1.15,r*.2,-r*.63);ctx.lineTo(r*.62,-r*.99);ctx.quadraticCurveTo(r*1.2,-r*.1,r*.72,r*.5);ctx.quadraticCurveTo(0,r*1.1,-r*.76,r*.45);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle=e.big?'#a1f9fa':'#ffb9ff';ctx.beginPath();ctx.ellipse(-r*.3,-r*.12,r*.12,r*.065,-.2,0,6.28);ctx.ellipse(r*.29,-r*.12,r*.12,r*.065,.2,0,6.28);ctx.fill();ctx.strokeStyle=glow;ctx.globalAlpha=.65;ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(-r*.5,r*.55);ctx.lineTo(-r*.8,r*1.2+Math.sin(phase*3)*3);ctx.moveTo(r*.4,r*.55);ctx.lineTo(r*.78,r*1.05);ctx.stroke();ctx.globalAlpha=1;ctx.restore();
  const bw=e.big?58:37,bh=4,yy=p.y-r-15;ctx.fillStyle='#07090fc9';ctx.fillRect(p.x-bw/2,yy,bw,bh);ctx.fillStyle=e.big?'#71dce3':'#e37bd0';ctx.fillRect(p.x-bw/2,yy,bw*clamp(e.hp/e.maxHp,0,1),bh);if(e.big){ctx.font='9px Noto Sans KR';ctx.textAlign='center';ctx.fillStyle='#d5faff';ctx.fillText('균열의 수호자',p.x,yy-5)}}
function drawPlayer(){const p=worldPoint(player.x,player.y),blink=player.invuln>0&&Math.floor(time*18)%2===0;ctx.save();ctx.translate(p.x,p.y);ctx.globalAlpha=blink?.46:1;ctx.fillStyle='#0009';ctx.beginPath();ctx.ellipse(0,15,20,8,0,0,6.28);ctx.fill();if(player.ultimate>0){ctx.strokeStyle=colors.cyan;ctx.globalAlpha=.38+Math.sin(time*7)*.18;ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,34+Math.sin(time*5)*4,0,6.28);ctx.stroke();ctx.globalAlpha=1}
  ctx.rotate(Math.atan2(player.faceY,player.faceX));ctx.fillStyle='#111724';ctx.beginPath();ctx.moveTo(-11,-7);ctx.lineTo(6,-10);ctx.lineTo(15,9);ctx.lineTo(-8,12);ctx.closePath();ctx.fill();ctx.fillStyle='#43515e';ctx.fillRect(-6,-8,13,16);ctx.fillStyle='#d1b798';ctx.beginPath();ctx.arc(4,-9,7,0,6.28);ctx.fill();ctx.fillStyle='#171822';ctx.beginPath();ctx.moveTo(-2,-14);ctx.lineTo(10,-16);ctx.lineTo(14,-9);ctx.lineTo(1,-8);ctx.closePath();ctx.fill();ctx.strokeStyle='#d9e8ed';ctx.lineWidth=3;ctx.shadowColor='#91d8f6';ctx.shadowBlur=10;ctx.beginPath();ctx.moveTo(3,0);ctx.lineTo(31,2);ctx.stroke();ctx.shadowBlur=0;ctx.strokeStyle='#80705e';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(6,1);ctx.stroke();ctx.restore();if(player.attackTimer>0){let a=Math.atan2(player.faceY,player.faceX);ctx.save();ctx.translate(p.x,p.y);ctx.strokeStyle='#f6f3dd';ctx.globalAlpha=player.attackTimer/.23;ctx.lineWidth=3;ctx.shadowColor='#d8f5ff';ctx.shadowBlur=15;ctx.beginPath();ctx.arc(0,0,55,a-.75,a+.75);ctx.stroke();ctx.restore()}}
function drawEffects(){for(const s of slashes){const p=worldPoint(s.x,s.y),k=s.life/s.max;ctx.save();ctx.translate(p.x,p.y);ctx.globalAlpha=Math.min(1,k*1.7);ctx.strokeStyle=s.color;ctx.shadowColor=s.color;ctx.shadowBlur=18;ctx.lineWidth=s.ring?2:5;ctx.beginPath();if(s.ring){let radius=s.r*(1-k*.6);ctx.arc(0,0,radius,0,6.28)}else ctx.arc(0,0,s.r,s.a-.72,s.a+.72);ctx.stroke();if(!s.ring){ctx.globalAlpha*=.45;ctx.lineWidth=12;ctx.beginPath();ctx.arc(0,0,s.r,s.a-.55,s.a+.55);ctx.stroke()}ctx.restore()}
  for(const p of particles){const q=worldPoint(p.x,p.y);ctx.globalAlpha=clamp(p.life/p.max,0,1);ctx.fillStyle=p.color;ctx.shadowColor=p.color;ctx.shadowBlur=8;ctx.beginPath();ctx.arc(q.x,q.y,p.size,0,6.28);ctx.fill()}ctx.globalAlpha=1;ctx.shadowBlur=0;for(const t of texts){const p=worldPoint(t.x,t.y);ctx.globalAlpha=clamp(t.life/t.max,0,1);ctx.font=`800 ${t.size}px Noto Sans KR`;ctx.textAlign='center';ctx.lineWidth=3;ctx.strokeStyle='#080a10';ctx.strokeText(t.text,p.x,p.y);ctx.fillStyle=t.color;ctx.fillText(t.text,p.x,p.y)}ctx.globalAlpha=1}
function drawWorldMark(){const p=worldPoint(0,0);ctx.save();ctx.globalAlpha=.18;ctx.strokeStyle='#d0b570';ctx.lineWidth=1;for(let i=0;i<3;i++){ctx.beginPath();ctx.arc(p.x,p.y,125+i*12,0,6.28);ctx.stroke()}for(let i=0;i<8;i++){let a=i*Math.PI/4;ctx.beginPath();ctx.moveTo(p.x+Math.cos(a)*110,p.y+Math.sin(a)*110);ctx.lineTo(p.x+Math.cos(a)*156,p.y+Math.sin(a)*156);ctx.stroke()}ctx.restore()}
function render(){if(!W||!H)return;ctx.setTransform(dpr,0,0,dpr,0,0);let sx=shake?rand(-shake,shake):0,sy=shake?rand(-shake,shake):0;shake=Math.max(0,shake-.6);ctx.save();ctx.translate(sx,sy);drawGround();drawWorldMark();drawDecor();let sorted=[...enemies].filter(e=>!e.dead).sort((a,b)=>a.y-b.y);for(const e of sorted)drawEnemy(e);drawPlayer();drawEffects();ctx.restore()}
function updateUI(){ui.levelText.textContent=player.level;ui.hpBar.style.width=`${100*player.hp/player.maxHp}%`;ui.hpText.textContent=`${Math.ceil(player.hp)} / ${player.maxHp}`;ui.mpBar.style.width=`${100*player.mp/player.maxMp}%`;ui.mpText.textContent=`${Math.floor(player.mp)} / ${player.maxMp}`;ui.xpText.textContent=`${Math.floor(player.xp)} / ${player.nextXp} XP`;ui.xpBar.style.width=`${100*player.xp/player.nextXp}%`;ui.attackText.textContent=player.attack;ui.goldText.textContent=player.gold;ui.questBar.style.width=`${Math.min(100,kills/5*100)}%`;for(const k of ['q','e','r']){const el=ui[{q:'skill1',e:'skill2',r:'skill3'}[k]],cool=skillState[k];el.classList.toggle('cooling',cool>0);el.classList.toggle('disabled',player.mp<skillDefs[k].cost);el.querySelector('.skill-cool').textContent=cool>0?cool.toFixed(1):''}}
