(()=>{'use strict';
const c=document.querySelector('#game'),x=c.getContext('2d'),$=id=>document.getElementById(id),R=(a,b)=>a+Math.random()*(b-a),C=(n,a,b)=>Math.max(a,Math.min(b,n));let W,H,D=1,last=0,t=0,shake=0;
function resize(){D=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;c.width=W*D;c.height=H*D;x.setTransform(D,0,0,D,0,0)}addEventListener('resize',resize);resize();
const p={x:0,y:0,dx:0,dy:0,fx:1,fy:0,hp:100,mhp:100,mp:60,mmp:60,lvl:1,xp:0,next:100,gold:0,atk:12,inv:0,ac:0,anim:0,dash:0,ult:0,dead:false},keys={},cool={q:0,e:0,r:0},def={q:[20,5],e:[30,8],r:[50,22]},col={purple:'#b58aff',flame:'#ff9c6d',cyan:'#6ce3ef',gold:'#f4d276'};let es=[],ps=[],ss=[],ts=[],trees=[],kills=0,boss=false,toast=0,notice=0,mv={x:0,y:0},joy=false,sound=false,audio;
function say(s){$('toast').textContent=s;$('toast').classList.add('show');toast=2}function notify(s){$('notice').querySelector('span').textContent=s;$('notice').classList.add('show');notice=2.8}function feed(s,k=''){let d=document.createElement('div');d.className='feed-line '+k;d.textContent=s;$('combatFeed').prepend(d);while($('combatFeed').children.length>4)$('combatFeed').lastChild.remove();setTimeout(()=>d.remove(),4800)}function beep(f=360,d=.08,type='sine'){if(!sound)return;try{audio??=new(window.AudioContext||webkitAudioContext)();let o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.value=f;g.gain.setValueAtTime(.05,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+d);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+d)}catch{}}
function scr(a,b){return{x:W/2+a-p.x,y:H/2+15+b-p.y}}function burst(a,b,color,n=12,power=130,size=3){for(let i=0;i<n;i++){let q=R(0,6.28),v=R(power*.25,power),life=R(.25,.65);ps.push({x:a,y:b,vx:Math.cos(q)*v,vy:Math.sin(q)*v,life,max:life,size:R(1,size),color})}}function text(a,b,s,color='#fff',size=13){ts.push({x:a,y:b,s,color,size,life:.8,max:.8,vy:-32})}function spawn(a,b,big=false){es.push({x:a,y:b,hp:big?240:38+p.lvl*7,max:big?240:38+p.lvl*7,r:big?27:16,speed:big?37:R(42,57),atk:big?16:7+p.lvl,cd:R(.5,1.8),hit:0,phase:R(0,8),big,dead:false})}for(let i=0;i<38;i++){let a=R(0,6.28),r=R(270,1100);trees.push({x:Math.cos(a)*r,y:Math.sin(a)*r,s:R(.65,1.5),rot:R(0,6.28),stone:Math.random()<.54})}for(let i=0;i<5;i++){let a=R(0,6.28),r=R(210,390);spawn(Math.cos(a)*r,Math.sin(a)*r)}
function nearest(range=Infinity){let best=null,bd=range;for(const e of es)if(!e.dead){let d=Math.hypot(e.x-p.x,e.y-p.y);if(d<bd){bd=d;best=e}}return best}function face(){let e=nearest(240);if(e){let d=Math.hypot(e.x-p.x,e.y-p.y)||1;p.fx=(e.x-p.x)/d;p.fy=(e.y-p.y)/d}}
function damage(e,n,k=0,color=col.gold){if(e.dead)return;e.hp-=n;e.hit=.17;text(e.x,e.y-e.r-8,Math.round(n),color,e.big?17:13);burst(e.x,e.y,color,e.big?9:6,75,2.4);if(k){let d=Math.hypot(e.x-p.x,e.y-p.y)||1;e.x+=(e.x-p.x)/d*k;e.y+=(e.y-p.y)/d*k}if(e.hp<=0){e.dead=true;kills++;p.xp+=e.big?120:32;p.gold+=e.big?100:12;burst(e.x,e.y,e.big?col.cyan:col.purple,e.big?38:20,180,4);text(e.x,e.y-25,e.big?'수호자 격파!':'처치!',e.big?col.cyan:col.gold,14);feed(e.big?'균열의 수호자를 처치했습니다!':'그림자 몬스터 처치  +32 XP','good');if(!e.big){$('questCount').textContent=`${Math.min(kills,5)} / 5`;if(kills>=5&&!boss)bossSpawn()}else{$('questCount').textContent='완료';$('questBar').style.width='100%';p.xp+=120;p.gold+=80;feed('의뢰 완료! +120 XP  +80 G','gold');notify('의뢰 완료 — 보상을 획득했습니다')}}}
