let ix=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0)+mv.x,iy=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0)+mv.y,m=Math.hypot(ix,iy);if(m>1){ix/=m;iy/=m}p.dx=ix;p.dy=iy;p.x+=ix*(p.ult?190:145)*dt;p.y+=iy*(p.ult?190:145)*dt;if(m>.08){p.fx=ix;p.fy=iy}
